  let raw;
  try { raw = fs.readFileSync('/dev/stdin', 'utf8'); }
  catch (e) { raw = fs.readFileSync(0, 'utf8'); }

  const tokens = raw.trim().split(/\s+/).map(Number);
  let idx = 0;
  const N = tokens[idx++];
  const K = tokens[idx++];
  const C = tokens[idx++];

  // Prefix sums
  const P = new Int32Array(N + 1);
  for (let i = 1; i <= N; i++) P[i] = P[i - 1] + tokens[idx++];

  const total = P[N];

  // Maximizar soma descoberta == minimizar soma coberta pelas K janelas de tamanho C
  const gap = N - K * C;      // celulas "livres" alem das obrigatoriamente cobertas
  const width = gap + 1;

  // W[i] = soma das C celulas terminando em i
  const W = new Int32Array(N + 1);
  for (let i = C; i <= N; i++) W[i] = P[i] - P[i - C];

  // DP: com j rotulos usados, a posicao da fronteira i satisfaz j*C <= i <= j*C + gap
  // prev[r] = minimo somatorio coberto com (j-1) rotulos dentro das primeiras (j-1)*C + r celulas
  let prev = new Int32Array(width);
  let cur = new Int32Array(width);

  for (let j = 1; j <= K; j++) {
    const s = j * C;
    cur[0] = prev[0] + W[s];
    for (let r = 1; r < width; r++) {
      const v = prev[r] + W[s + r];       // colar rotulo terminando em s+r
      const c = cur[r - 1];               // nao colar rotulo terminando em s+r
      cur[r] = v < c ? v : c;
    }
    const t = prev; prev = cur; cur = t;
  }

  process.stdout.write((total - prev[width - 1]) + '\n');
})();
